// ⚙️ CONFIG DES GARAGES — une entrée par garage (même id que le YAML côté serveur)
const GARAGES = {
  "garage-demo": {
    calendarId: "primary",               // ou l'ID d'un agenda dédié au garage
    timezone: "Europe/Paris",
    notifyEmail: "toi@exemple.com",      // qui reçoit les messages et rapports d'appel
    smsFrom: "+33100000000",             // numéro Twilio (ou Sender ID alphanumérique, ex. "GARAGEDEMO")
  },
  "dentiste-demo": {
    calendarId: "ID_AGENDA_CABINET@group.calendar.google.com",
    timezone: "Europe/Paris",
    notifyEmail: "toi@exemple.com",
    smsFrom: "+33100000001",
  },
};

const body = $input.first().json.body;
const g = GARAGES[body.tenant_id];
if (!g) throw new Error(`Garage inconnu : ${body.tenant_id}`);
return [{ json: { calendarId: g.calendarId, timeMin: body.time_min, timeMax: body.time_max } }];

// Google renvoie { items: [...] }. On ne garde que ce qui occupe l'atelier.
const items = $input.first().json.items || [];
const events = items
  .filter(e => e.status !== 'cancelled' && e.transparency !== 'transparent')
  .map(e => ({
    // journée entière -> "2026-10-05" (le serveur la traite comme "garage fermé")
    start: e.start.dateTime || e.start.date,
    end: e.end.dateTime || e.end.date,
  }));
return [{ json: { events } }];

// ⚙️ CONFIG DES GARAGES — une entrée par garage (même id que le YAML côté serveur)
const GARAGES = {
  "garage-demo": {
    calendarId: "primary",               // ou l'ID d'un agenda dédié au garage
    timezone: "Europe/Paris",
    notifyEmail: "toi@exemple.com",      // qui reçoit les messages et rapports d'appel
    smsFrom: "+33100000000",             // numéro Twilio (ou Sender ID alphanumérique, ex. "GARAGEDEMO")
  },
  "dentiste-demo": {
    calendarId: "ID_AGENDA_CABINET@group.calendar.google.com",
    timezone: "Europe/Paris",
    notifyEmail: "toi@exemple.com",
    smsFrom: "+33100000001",
  },
};

const body = $input.first().json.body;
const g = GARAGES[body.tenant_id];
if (!g) throw new Error(`Garage inconnu : ${body.tenant_id}`);
const a = body.appointment;
// Garage : véhicule + immat. Cabinet dentaire : nouveau patient ou non. Les lignes null sont retirées.
const isPatient = a.new_patient === true || a.new_patient === false;
const vehicle = a.vehicle ? `${a.vehicle}${a.plate ? ' (' + a.plate + ')' : ''}` : null;
const description = [
  `${isPatient ? 'Patient' : 'Client'} : ${a.customer_name}`,
  `Téléphone : ${a.customer_phone || '—'}`,
  vehicle ? `Véhicule : ${vehicle}` : null,
  isPatient ? `Dossier : ${a.new_patient ? 'nouveau patient' : 'déjà patient'}` : null,
  `Motif : ${a.service_label}`,
  `Demande : ${a.problem_description}`,
  '',
  'Pris par l\'agent vocal IA',
].filter(l => l !== null).join('\n');
const event = {
  summary: [a.service_label, a.customer_name, a.vehicle, a.new_patient === true ? 'NOUVEAU PATIENT' : '']
    .filter(Boolean).join(' – '),
  description,
  start: { dateTime: a.start, timeZone: g.timezone },
  end: { dateTime: a.end, timeZone: g.timezone },
  extendedProperties: { private: { source: 'agent-vocal', customer_phone: a.customer_phone || '' } },
};
const sms = `${a.garage_name} : votre RDV du ${a.label} est confirmé (${a.service_label}). `
  + `Adresse : ${a.garage_address}. Pour modifier ou annuler, appelez-nous.`;
return [{ json: { calendarId: g.calendarId, event, smsFrom: g.smsFrom, smsTo: a.customer_phone || '', sms } }];
